    type: "ومضة تفسيرية",
    source: "تفسير السعدي، وتفسير ابن كثير",
    textEn: "Even after the trial had ended, the acknowledgment of the soul's nature came: \"indeed prone to evil.\" Choosing the intensive form \"ammarah\" indicates a persistent inclination toward evil, not merely one isolated occurrence.",
