    textAr: "موسى لم يحدد نوع الخير الذي يطلبه، ولم يقل: أرزقني عملًا أو طعامًا؛ بل قال: «لما أنزلت إلي من خير فقير». أظهر حاله من الافتقار وترك تفصيل العطاء. فجاءت العبارة أوسع من طلب واحد.",
