    textAr: "«الراجفة» من الرجف والاضطراب، و«الرادفة» من الردف أي ما يأتي خلف الشيء. فاسما الحدثين يحملان ترتيب وقوعهما داخل اللفظ.",
    type: "معاني كلمات",
