    textAr: "اختير حرف «على» بدل «في»؛ فصوّر أهل الهدى كأنهم مستعلون على طريق ثابت متمكنون منه، لا مجرد عابرين فيه. وهذا مناسب لما قبلها من صفاتهم المتتابعة.",
