    textAr: "الآية نفت وصفين مختلفين: «ضل» و«غوى». فالأول في معنى فقد الطريق، والثاني في معنى الانحراف مع اتباع الهوى؛ فاجتماعهما يحيط بنفي الخطأ في الطريق والقصد.",
